package com.personal.assistant.module.reminder.service;
import com.personal.assistant.common.exception.*;import com.personal.assistant.module.reminder.entity.*;import com.personal.assistant.module.reminder.mapper.*;import org.springframework.http.MediaType;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.time.LocalDateTime;import java.util.Map;
@Service public class NotificationService {private final NotificationChannelMapper channels;private final NotificationLogMapper logs;private final SecretCryptoService crypto;private final RestClient client=RestClient.create();public NotificationService(NotificationChannelMapper c,NotificationLogMapper l,SecretCryptoService x){channels=c;logs=l;crypto=x;}public void send(Long userId,Long reminderId,Long channelId,String title,String content){NotificationChannel c=channels.selectById(channelId);if(c==null||!userId.equals(c.getUserId())||!Boolean.TRUE.equals(c.getEnabled()))throw new BusinessException(ErrorCode.BUSINESS_ERROR,"通知通道不可用");boolean ok=false;String msg="发送成功";try{String url=crypto.decrypt(c.getWebhookEncrypted());client.post().uri(url).contentType(MediaType.APPLICATION_JSON).body(Map.of("title",title,"text",content==null?title:content)).retrieve().toBodilessEntity();ok=true;}catch(Exception e){msg=e.getMessage();throw new BusinessException(ErrorCode.INTEGRATION_ERROR,"Webhook 发送失败");}finally{NotificationLog log=new NotificationLog();log.setUserId(userId);log.setReminderId(reminderId);log.setChannelId(channelId);log.setSuccess(ok);log.setMessage(msg);log.setCreatedAt(LocalDateTime.now());logs.insert(log);}}}